    //
    //       string_first_of_or_end, string_first_of_max and string_last_of_or_end -- the rest of the byte hunts.
    //
    //       All three are string_first_of with one thing changed: what to return when the
    //       byte is absent, where to stop, and which match to keep. The machinery
    //       underneath is the one string_first_of already uses -- broadcast the byte across
    //       a word, exclusive-or, and the byte that matched is the byte that is
    //       now zero -- so what follows is mostly the differences.
    //
